    try std.testing.expectEqual(std.hash.Crc32.hash(buf[1..]), hash(buf[1..]));
    try std.testing.expectEqual(std.hash.Crc32.hash(buf[3 .. 3 + 1001]), hash(buf[3 .. 3 + 1001]));
}
